{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://xteink.example/schemas/xtapp-manifest.schema.json",
  "title": "XTApp Manifest",
  "type": "object",
  "required": ["app_id", "display_name", "version", "api", "entry"],
  "properties": {
    "app_id": { "type": "string", "pattern": "^[a-z0-9_]+-[a-f0-9]{8}$" },
    "name": { "type": "string" },
    "display_name": { "type": "string", "minLength": 1 },
    "version": { "type": "string", "pattern": "^\\d+\\.\\d+\\.\\d+(?:[-+][0-9A-Za-z.-]+)?$" },
    "api": { "type": "string", "enum": ["0.5", "0.6", "0.7", "0.8"] },
    "entry": { "type": "string", "pattern": "^[A-Za-z0-9_.-]+\\.lua$" },
    "author": { "type": "string" },
    "description": { "type": "string" },
    "permissions": {
      "type": "array",
      "items": { "enum": ["net.http"] },
      "uniqueItems": true,
      "description": "ctx.net is available only after this permission is declared; net.http is the only value today"
    },
    "display": {
      "type": "object",
      "properties": {
        "orientation": { "enum": ["system", "portrait", "landscape"] }
      },
      "additionalProperties": false
    },
    "preload_assets": {
      "type": "array",
      "items": { "type": "string", "pattern": "^[A-Za-z0-9_-]{1,23}$" },
      "uniqueItems": true
    },
    "app_icon_s": { "type": "string", "pattern": "^[A-Za-z0-9_-]{1,23}$" },
    "app_icon_l": { "type": "string", "pattern": "^[A-Za-z0-9_-]{1,23}$" },
    "splash": { "type": "string", "pattern": "^[A-Za-z0-9_-]{1,23}$" },
    "data_files": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name", "format", "max_bytes"],
        "properties": {
          "name": { "type": "string", "pattern": "^[A-Za-z0-9._-]{1,64}$" },
          "format": { "enum": ["tsv", "txt"] },
          "max_bytes": { "type": "integer", "minimum": 1, "maximum": 1048576 }
        },
        "additionalProperties": false
      }
    },
    "lockscreen": {
      "type": "object",
      "required": ["enabled"],
      "properties": {
        "enabled": { "type": "boolean" },
        "entry": { "type": "string", "pattern": "^[A-Za-z0-9_.-]+\\.lua$" },
        "interval_sec": { "type": "integer", "minimum": 0 }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": true
}

